export function getWeapon(id: string): WeaponData | undefined {
  return WEAPONS.find((w) => w.id === id);
}

export function weaponsForType(weaponType: string): WeaponData[] {
  return WEAPONS.filter((w) => w.weaponType === weaponType);
}
